8	const buildFindAllQuery = (query: any, id: number | undefined) => {
9	  const queries: any = [];
10	  const orAuthorQuery = [];
11	  const andAuthorQuery = [];
12	
13	  orAuthorQuery.push({
14	    demo: {
15	      equals: true,
16	    },
17	  });
18	
19	  if (id) {
20	    orAuthorQuery.push({
21	      id: {
22	        equals: id,
23	      },
24	    });
25	  }
26	
27	  if ('author' in query) {
28	    andAuthorQuery.push({
29	      username: {
30	        equals: query.author,
31	      },
32	    });
33	  }
34	
35	  const authorQuery = {
36	    author: {
37	      OR: orAuthorQuery,
38	      AND: andAuthorQuery,
39	    },
40	  };
41	
42	  queries.push(authorQuery);
43	
44	  if ('tag' in query) {
45	    queries.push({
46	      tagList: {
47	        some: {
48	          name: query.tag,
49	        },
50	      },
51	    });
52	  }
53	
54	  if ('favorited' in query) {
55	    queries.push({
56	      favoritedBy: {
57	        some: {
58	          username: {
59	            equals: query.favorited,
60	          },
61	        },
62	      },
63	    });
64	  }
65	
66	  return queries;
67	};
68	
69	// Article list limits (team vault: policy-article-list-limit.md, Neuron question 1).
70	// A requested limit above the maximum is clamped to the maximum, not rejected.
71	export const ARTICLE_LIST_MAX_LIMIT = 50;
72	export const ARTICLE_LIST_DEFAULT_LIMIT = 10;
73	
74	export const getArticles = async (query: any, id?: number) => {
75	  const andQueries = buildFindAllQuery(query, id);
76	  const articlesCount = await prisma.article.count({
77	    where: {
78	      AND: andQueries,
79	    },
80	  });
81	
82	  const articles = await prisma.article.findMany({
83	    where: { AND: andQueries },
84	    orderBy: {
85	      createdAt: 'desc',
86	    },
87	    skip: Number(query.offset) || 0,
88	    take: Math.min(Number(query.limit) || ARTICLE_LIST_DEFAULT_LIMIT, ARTICLE_LIST_MAX_LIMIT),
89	    include: {
90	      tagList: {
91	        select: {
92	          name: true,
93	        },
94	      },
95	      author: {
96	        select: {
97	          username: true,
98	          bio: true,
99	          image: true,
100	          followedBy: true,
101	        },
102	      },
103	      favoritedBy: true,
104	      _count: {
105	        select: {
106	          favoritedBy: true,
107	        },
108	      },
109	    },
110	  });
111	
112	  return {
113	    articles: articles.map((article: any) => articleMapper(article, id)),
114	    articlesCount,
115	  };
116	};
117	
118	export const getFeed = async (offset: number, limit: number, id: number) => {
119	  const articlesCount = await prisma.article.count({
120	    where: {
121	      author: {
122	        followedBy: { some: { id: id } },
123	      },
124	    },
125	  });
126	
127	  const articles = await prisma.article.findMany({
128	    where: {
129	      author: {
130	        followedBy: { some: { id: id } },
131	      },
132	    },
133	    orderBy: {
134	      createdAt: 'desc',
135	    },
136	    skip: offset || 0,
137	    take: limit || 10,
138	    include: {
139	      tagList: {
140	        select: {
141	          name: true,
142	        },
143	      },
144	      author: {
145	        select: {
146	          username: true,
147	          bio: true,
148	          image: true,
149	          followedBy: true,
150	        },
151	      },
152	      favoritedBy: true,
153	      _count: {
154	        select: {
155	          favoritedBy: true,
156	        },
157	      },
158	    },
159	  });
160	
161	  return {
162	    articles: articles.map((article: any) => articleMapper(article, id)),
163	    articlesCount,
164	  };
165	};
