167	export const createArticle = async (article: any, id: number) => {
168	  const { title, description, body, tagList } = article;
169	  const tags = Array.isArray(tagList) ? tagList : [];
170	
171	  if (!title) {
172	    throw new HttpException(422, { errors: { title: ["can't be blank"] } });
173	  }
174	
175	  if (!description) {
176	    throw new HttpException(422, { errors: { description: ["can't be blank"] } });
177	  }
178	
179	  if (!body) {
180	    throw new HttpException(422, { errors: { body: ["can't be blank"] } });
181	  }
182	
183	  const slug = `${slugify(title)}-${id}`;
184	
185	  const existingTitle = await prisma.article.findUnique({
186	    where: {
187	      slug,
188	    },
189	    select: {
190	      slug: true,
191	    },
192	  });
193	
194	  if (existingTitle) {
195	    throw new HttpException(422, { errors: { title: ['must be unique'] } });
196	  }
197	
198	  const {
199	    authorId,
200	    id: articleId,
201	    ...createdArticle
202	  } = await prisma.article.create({
203	    data: {
204	      title,
205	      description,
206	      body,
207	      slug,
208	      tagList: {
209	        connectOrCreate: tags.map((tag: string) => ({
210	          create: { name: tag },
211	          where: { name: tag },
212	        })),
213	      },
214	      author: {
215	        connect: {
216	          id: id,
217	        },
218	      },
219	    },
220	    include: {
221	      tagList: {
222	        select: {
223	          name: true,
224	        },
225	      },
226	      author: {
227	        select: {
228	          username: true,
229	          bio: true,
230	          image: true,
231	          followedBy: true,
232	        },
233	      },
234	      favoritedBy: true,
235	      _count: {
236	        select: {
237	          favoritedBy: true,
238	        },
239	      },
240	    },
241	  });
242	
243	  return articleMapper(createdArticle, id);
244	};
