246	export const getArticle = async (slug: string, id?: number) => {
247	  const article = await prisma.article.findUnique({
248	    where: {
249	      slug,
250	    },
251	    include: {
252	      tagList: {
253	        select: {
254	          name: true,
255	        },
256	      },
257	      author: {
258	        select: {
259	          username: true,
260	          bio: true,
261	          image: true,
262	          followedBy: true,
263	        },
264	      },
265	      favoritedBy: true,
266	      _count: {
267	        select: {
268	          favoritedBy: true,
269	        },
270	      },
271	    },
272	  });
273	
274	  if (!article) {
275	    throw new HttpException(404, { errors: { article: ['not found'] } });
276	  }
277	
278	  return articleMapper(article, id);
279	};
