294	export const updateArticle = async (article: any, slug: string, id: number) => {
295	  let newSlug = null;
296	
297	  const existingArticle = await await prisma.article.findFirst({
298	    where: {
299	      slug,
300	    },
301	    select: {
302	      author: {
303	        select: {
304	          id: true,
305	          username: true,
306	        },
307	      },
308	    },
309	  });
310	
311	  if (!existingArticle) {
312	    throw new HttpException(404, {});
313	  }
314	
315	  if (existingArticle.author.id !== id) {
316	    throw new HttpException(403, {
317	      message: 'You are not authorized to update this article',
318	    });
319	  }
320	
321	  if (article.title) {
322	    newSlug = `${slugify(article.title)}-${id}`;
323	
324	    if (newSlug !== slug) {
325	      const existingTitle = await prisma.article.findFirst({
